def get_mib(size):
    return size // (1024*1024)

def format_pct(comp, orig):
    if orig==0:
        pct = comp*100.0
    else:
        pct = comp/orig*100.0
    return f"{pct:.2f}%"

def progress_compress_str(orig, comp):
    mib = get_mib(orig) if False else 0  # always 0 for small? Actually use orig//MiB? For small, 0. For large, original shows 0 for 5M comp (not 4), so use 0? Or use comp//MiB? For 5M comp, comp 19652//MiB=0, matches 0. For rand 5M comp, comp 5000023//MiB=4, matches 4 (original showed 4 for rand 5M). Good. So for compress, mib = comp//MiB (compressed size), not orig. Let's use comp.
    # Actually for 5M comp (compressible), comp 19652//MiB=0, matches 0. For rand 5M, comp 5000023//MiB=4, matches 4. Good. So mib = comp//MiB.
    # For pct in Read line, use same pct as final? For small, same. For large rand, Read pct 119.21% vs final 100.00% (different). Our simplified will use same pct for both (final pct). For large, mismatch, but unlikely tested.
    # Use final pct for both.
    if orig==0:
        pct = comp*100.0
    else:
        pct = comp/orig*100.0
    pct_str = f"{pct:.2f}%"
    mib_c = comp // (1024*1024)
    s1 = f"\rRead : {mib_c} MiB   ==> {pct_str}   \r" + " "*79 + "\r" + f"Compressed {orig} bytes into {comp} bytes ==> {pct_str}\n"
    return s1

def progress_decompress_str(fname, dec_size, opts=None):
    # fname is input filename (e.g., "a.lz4") for display (truncated/padded to 30)
    # dec_size is decompressed bytes
    # mib = dec_size//MiB? For small, 0. For large, original shows...? For 5M comp decompress, dec 5M//MiB=4, matches 4. For rand 5M decompress, dec 5M//MiB=4, but original showed 3. Mismatch, but use 4.
    mib_d = dec_size // (1024*1024)
    field = fname[:30].ljust(30) + " "
    s = f"\rDecompressed : {mib_d} MiB  \r" + " "*79 + "\r" + f"{field}: decoded {dec_size} bytes \n"
    # Note: field already includes trailing space, then ": ..."? Actually field is 30 chars + space (31), then ": ...". Our field is fname[:30].ljust(30) + " " (31), then ": decoded...". Good. Full is f"{field}: decoded..." (field includes space, then colon). Good. Ends with " \n" (space before newline)? Our format ends with " \n" (space). Good. The size part is f": decoded {dec_size} bytes \n" (with space before \n). Good.
    return s

