def is_stdin_input(name):
    return name=="-" or name=="stdin"

def is_stdout_output(name):
    return name=="-" or name=="stdout"

def is_null_output(name):
    return name=="null"

def print_already_exists_no_prompt(path):
    # for -q or -m: "<path> already exists; not overwritten  \n" (2 spaces before \n)
    eprint(f"{path} already exists; not overwritten  \n")

def prompt_overwrite_single(path, opts, stdin_buffer=None, is_stdin_input=False):
    # stdin_buffer: if is_stdin_input True, stdin_buffer is all stdin data (bytes) already read; answer is first line, remaining is data.
    # If is_stdin_input False, stdin_buffer is None, need to read answer from sys.stdin (one line).
    # Returns (overwrite_bool, remaining_stdin_data_or_None)
    # Prints prompt message (without newline) to stderr.
    # If quiet (eff<0? Actually prompt only when not quiet? Caller should check: if quiet (eff<0, i.e., quiet>verbose), then no prompt, just print already_exists_no_prompt and return False. This function is called only when need prompt (i.e., eff>=0, not multiple, not force, output exists).
    # For multiple (-m), never prompt (caller handles).
    prompt_msg = f"{path} already exists; do you want to overwrite (y/N) ? "
    eprint(prompt_msg)
    ans_char = None
    remaining = None
    if is_stdin_input:
        data = stdin_buffer if stdin_buffer is not None else b""
        # split at first \n
        if b"\n" in data:
            idx = data.index(b"\n")
            first_line = data[:idx+1]  # include \n
            remaining = data[idx+1:]
        else:
            first_line = data
            remaining = b""
        if len(first_line)>0:
            ans_char = chr(first_line[0]) if isinstance(first_line[0], int) else first_line[0]
        else:
            ans_char = ""
        # check y/Y
        if ans_char=="y" or ans_char=="Y":
            return True, remaining
        else:
            eprint(f"    not overwritten  \n")
            return False, remaining
    else:
        # read one line from stdin (sys.stdin.buffer)
        try:
            # Use sys.stdin.buffer.readline() to read one line (blocks until newline or EOF). For pipe with no data (EOF), returns b"" immediately. For tty, blocks until Enter.
            # Need to handle that sys.stdin.buffer may have been already read? For file input case, stdin hasn't been read yet (since input is file, not stdin), so buffer still has answer.
            # However, if stdin is empty (EOF), readline returns b"".
            line = sys.stdin.buffer.readline()
            if line is None:
                line=b""
        except Exception:
            line=b""
        if len(line)>0:
            # first byte
            b0 = line[0] if isinstance(line[0], int) else ord(line[0])
            ans_char = chr(b0)
        else:
            ans_char=""
        if ans_char=="y" or ans_char=="Y":
            return True, None
        else:
            eprint(f"    not overwritten  \n")
            return False, None

