def expand_recursive_if_needed(opts, files):
    if opts.recursive:
        return collect_recursive(files)
    return files

def is_regular_file(path):
    try:
        st = os.stat(path)
        return stat.S_ISREG(st.st_mode)
    except:
        return False

def do_list_main(opts, files, prog):
    # --list mode: files can be 0 (header only), 1+, multiple (with or without -m, same). No output file, just list to stdout.
    # Returns exit code.
